/* ============================================================ Expenses, Accounts */
const catIcon = (c) => (EXP_CATS.find(x => x[0] === c) || [0, 'Coins'])[1];
const Expenses = { components: { Header, Icon, Pill, Btn, Empty, Chips, StickyBar, DayHead, RowsCard, IconTile, Fab, Sheet },
  setup() {
    const rows = computed(() => EXPENSES.filter(e => S.expCat === 'all' || e.cat === S.expCat));
    const groups = computed(() => { const g = []; rows.value.forEach(e => { let x = g.find(y => y.day === e.day); if (!x) g.push(x = { day: e.day, rows: [] }); x.rows.push(e); }); return g; });
    const owner = computed(() => S.role === 'owner'); const cur = computed(() => EXPENSES.find(e => e.id === S.expOpen));
    const decide = (yes) => { cur.value.st = yes ? 'ok' : 'declined'; S.expOpen = null; toast(yes ? 'Approved' : 'Declined'); };
    const photo = ref(false);
    const save = () => { const n = S.newExp; EXPENSES.unshift({ id: 'EXP-00' + (37 + EXPENSES.length - 4), cat: n.cat, note: n.note || n.cat, amt: n.amt, acct: n.acct, day: 'Today', by: S.role === 'owner' ? 'Amina' : 'Rehema', st: S.role === 'owner' ? 'ok' : 'waiting' }); S.sheet = null; toast(S.role === 'owner' ? 'Expense saved' : 'Sent to Amina'); S.newExp = { amt: 0, cat: 'Transport', acct: 'Cash drawer', note: '' }; photo.value = false; };
    return { S, rows, groups, owner, cur, decide, save, photo, EXP_CATS, catIcon, money, week: EXPENSES.reduce((t, e) => t + e.amt, 0) };
  },
  template: `<div class="relative flex min-h-0 flex-1 flex-col"><Header title="Expenses"/>
    <div class="scroll min-h-0 flex-1 overflow-y-auto"><StickyBar><Chips v-model="S.expCat" :items="[['all', 'All'], ...EXP_CATS.map(c => [c[0], c[0].split(' ')[0]])]"/></StickyBar>
      <div class="p-3 pb-20"><div class="mb-3 flex items-center justify-between rounded-xl bg-muted/60 px-4 py-3"><span class="text-sm text-muted-foreground">This week</span><b class="text-base tnum">{{ money(week) }}</b></div>
        <Empty v-if="!rows.length" icon="Coins" title="No expenses here"/>
        <div v-for="g in groups" :key="g.day"><DayHead :day="g.day" :note="money(g.rows.reduce((t, e) => t + e.amt, 0))"/><RowsCard><button v-for="(e, i) in g.rows" :key="e.id" type="button" :class="['press flex w-full items-center gap-3 px-3.5 py-2.5 text-left', i ? 'border-t' : '']" @click="S.expOpen = e.id">
          <IconTile :icon="catIcon(e.cat)" :tone="e.st === 'waiting' ? 'warning' : 'muted'"/><span class="min-w-0 flex-1"><span class="block truncate text-sm font-medium">{{ e.note }}</span><span class="block truncate text-xs text-muted-foreground tnum">{{ e.id }} · {{ e.acct }} · {{ e.by }}</span></span>
          <span class="flex flex-col items-end gap-1"><span class="text-sm font-semibold tnum">{{ money(e.amt) }}</span><Pill v-if="e.st === 'waiting'" tone="warning">{{ owner ? 'Needs you' : 'Waits for Amina' }}</Pill></span></button></RowsCard></div></div></div>
    <Fab label="Add an expense" @click="S.sheet = 'newexp'"/>
    <Sheet :open="!!cur" :title="cur ? cur.note : ''" :sub="cur ? cur.id + ' · ' + cur.cat : ''" @close="S.expOpen = null"><div v-if="cur" class="px-4 pb-4"><p class="text-2xl font-semibold tnum">{{ money(cur.amt) }}</p><p class="mt-1 text-sm text-muted-foreground">Paid from {{ cur.acct }} · {{ cur.day }} · by {{ cur.by }}</p><p v-if="cur.st === 'waiting' && !owner" class="mt-3 flex items-center gap-2 rounded-md bg-warning/10 p-3 text-sm text-warning"><Icon name="Hourglass" :size="16"/>Waiting for Amina to approve.</p></div>
      <template v-if="cur && cur.st === 'waiting'" #footer><div v-if="owner" class="grid grid-cols-2 gap-2"><Btn v="outline" @click="decide(false)">Decline</Btn><Btn @click="decide(true)">Approve</Btn></div><Btn v-else v="outline" full @click="S.expOpen = null; toast('Request taken back')">Take it back</Btn></template></Sheet>
    <Sheet :open="S.sheet === 'newexp'" title="Add an expense" @close="S.sheet = null"><div class="space-y-4 px-4 pb-4">
      <div><p class="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Amount</p><label class="mt-1.5 flex h-12 items-center gap-2 rounded-md border-2 border-primary px-3"><span class="text-sm text-muted-foreground">TZS</span><input v-model.number="S.newExp.amt" type="text" inputmode="numeric" pattern="[0-9]*" aria-label="Amount" class="min-w-0 flex-1 bg-transparent text-right text-xl font-semibold tnum outline-none"></label></div>
      <div><p class="mb-1.5 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">What for</p><div class="flex flex-wrap gap-2"><button v-for="c in EXP_CATS" :key="c[0]" type="button" @click="S.newExp.cat = c[0]" :class="['press h-8 rounded-md px-3 text-sm font-medium', S.newExp.cat === c[0] ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground']">{{ c[0] }}</button></div></div>
      <div><p class="mb-1.5 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Paid from</p><div class="flex flex-wrap gap-2"><button v-for="a in (owner ? ['Cash drawer', 'Lipa Namba', 'M-Pesa wallet', 'CRDB bank'] : ['Cash drawer'])" :key="a" type="button" @click="S.newExp.acct = a" :class="['press h-8 rounded-md px-3 text-sm font-medium', S.newExp.acct === a ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground']">{{ a }}</button></div></div>
      <input v-model="S.newExp.note" placeholder="Note (optional)" aria-label="Note" class="flex h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm shadow-sm outline-none focus-visible:ring-1 focus-visible:ring-ring">
      <button type="button" class="press flex h-9 w-full items-center justify-center gap-2 rounded-md border border-dashed text-sm font-medium" @click="photo = !photo; toast(photo ? 'Photo removed' : 'Camera opens, then the photo is attached')"><Icon name="Camera" :size="16"/>{{ photo ? 'Photo attached' : 'Photo of the receipt' }}</button>
      <p v-if="!owner" class="text-xs text-muted-foreground">Expenses wait for Amina before they count.</p></div>
      <template #footer><Btn full :disabled="!S.newExp.amt" @click="save">{{ owner ? 'Save expense' : 'Send to Amina' }}</Btn></template></Sheet></div>` };

const Accounts = { components: { Header, Icon, Pill, Btn, IconTile, Fab, Sheet, FooterBar },
  setup() {
    const total = computed(() => ACCOUNTS.reduce((t, a) => t + a.bal, 0)); const from = ref('Cash drawer'), to = ref('Lipa Namba'), amt = ref(0);
    const doTransfer = () => { acct(from.value).bal -= amt.value; acct(to.value).bal += amt.value; S.sheet = null; toast(money(amt.value) + ' moved to ' + to.value); amt.value = 0; };
    return { S, ACCOUNTS, total, from, to, amt, doTransfer, money, money0, go, toast };
  },
  template: `<div class="relative flex min-h-0 flex-1 flex-col"><Header title="Accounts"/>
    <div class="scroll min-h-0 flex-1 overflow-y-auto"><div class="space-y-3 p-3 pb-20">
      <section class="rise rounded-xl border bg-card p-4"><p class="text-xs text-muted-foreground">All the shop's money</p><p class="text-2xl font-semibold tnum">{{ money(total) }}</p><button type="button" class="press mt-3 flex h-9 items-center gap-2 rounded-md border px-3 text-sm font-medium shadow-sm" @click="S.sheet = 'transfer'"><Icon name="ArrowLeftRight" :size="15"/>Move money</button></section>
      <button v-for="a in ACCOUNTS" :key="a.id" type="button" class="press rise flex w-full items-center gap-3 rounded-xl border bg-card p-3.5 text-left" @click="S.accId = a.id; S.accTab = 'history'; go('account')">
        <span class="grid h-9 w-9 shrink-0 place-items-center rounded-md text-white" :style="{ background: a.c }"><Icon :name="a.icon" :size="17"/></span><span class="min-w-0 flex-1"><span class="block truncate text-sm font-medium">{{ a.name }}</span><span class="block text-xs text-muted-foreground">{{ a.kind }} · checked {{ a.rec }}</span></span>
        <span class="text-right"><span class="block text-sm font-semibold tnum">{{ money(a.bal) }}</span><Pill v-if="a.gap" tone="warning">{{ money0(a.gap) }}</Pill></span></button></div></div>
    <Fab label="New account" @click="toast('New account: name, kind and opening balance')"/>
    <Sheet :open="S.sheet === 'transfer'" title="Move money" sub="Both accounts change by the same amount" @close="S.sheet = null"><div class="space-y-4 px-4 pb-4">
      <div><p class="mb-1.5 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">From</p><div class="flex flex-wrap gap-2"><button v-for="a in ACCOUNTS" :key="a.id" type="button" @click="from = a.name; if (to === a.name) to = ACCOUNTS.find(x => x.name !== a.name).name" :class="['press h-8 rounded-md px-3 text-sm font-medium', from === a.name ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground']">{{ a.name }}</button></div></div>
      <div><p class="mb-1.5 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">To</p><div class="flex flex-wrap gap-2"><button v-for="a in ACCOUNTS.filter(x => x.name !== from)" :key="a.id" type="button" @click="to = a.name" :class="['press h-8 rounded-md px-3 text-sm font-medium', to === a.name ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground']">{{ a.name }}</button></div></div>
      <label class="flex h-12 items-center gap-2 rounded-md border-2 border-primary px-3"><span class="text-sm text-muted-foreground">TZS</span><input v-model.number="amt" type="text" inputmode="numeric" pattern="[0-9]*" aria-label="Amount" class="min-w-0 flex-1 bg-transparent text-right text-xl font-semibold tnum outline-none"></label></div>
      <template #footer><Btn full :disabled="!amt" @click="doTransfer">Move {{ money(amt || 0) }}</Btn></template></Sheet></div>` };

const AccountPage = { components: { Header, Icon, Pill, Btn, Seg, FooterBar, Sheet },
  setup() {
    const a = computed(() => ACCOUNTS.find(x => x.id === S.accId) || ACCOUNTS[0]);
    const hist = computed(() => [...PAYMENTS.filter(p => p.acct === a.value.name).map(p => ({ k: 'in', t: 'Payment ' + p.id, sub: cust(p.c).name, amt: p.amt, day: p.day })), ...EXPENSES.filter(e => e.acct === a.value.name && e.st === 'ok').map(e => ({ k: 'out', t: e.id, sub: e.note, amt: -e.amt, day: e.day }))]);
    const counted = ref(0); watch(() => S.sheet, (v) => { if (v === 'recon') counted.value = a.value.bal; });
    const rec = () => { a.value.gap = counted.value - a.value.bal; a.value.rec = '13 Oct'; S.sheet = null; toast(a.value.gap ? 'Checked, with a gap of ' + money0(a.value.gap) : 'Checked, it matches'); };
    return { S, a, hist, counted, rec, money, money0 };
  },
  template: `<div class="flex min-h-0 flex-1 flex-col"><Header :title="a.name" pushed hide-search/>
    <div class="scroll min-h-0 flex-1 overflow-y-auto"><div class="space-y-3 p-3 pb-6">
      <section class="rise rounded-xl border bg-card p-4"><div class="flex items-center gap-3"><span class="grid h-11 w-11 shrink-0 place-items-center rounded-md text-white" :style="{ background: a.c }"><Icon :name="a.icon" :size="20"/></span><div><p class="text-xs text-muted-foreground">{{ a.kind }}</p><p class="text-2xl font-semibold tnum">{{ money(a.bal) }}</p></div></div><p class="mt-3 text-xs text-muted-foreground">Last checked {{ a.rec }}{{ a.gap ? ' · ' + money0(a.gap) + ' gap' : ' · it matched' }}</p></section>
      <Seg v-model="S.accTab" :tabs="[{ id: 'history', label: 'History' }, { id: 'checks', label: 'Checks' }]"/>
      <div v-if="S.accTab === 'history'" class="overflow-hidden rounded-xl border bg-card"><div v-for="(h, i) in hist" :key="i" :class="['flex items-center gap-3 px-3.5 py-2.5', i ? 'border-t' : '']"><span :class="['grid h-9 w-9 shrink-0 place-items-center rounded-md', h.k === 'in' ? 'bg-success/15 text-success' : 'bg-muted text-muted-foreground']"><Icon :name="h.k === 'in' ? 'ArrowDownLeft' : 'ArrowUpRight'" :size="16"/></span><span class="min-w-0 flex-1"><span class="block truncate text-sm font-medium">{{ h.t }}</span><span class="block truncate text-xs text-muted-foreground">{{ h.sub }} · {{ h.day }}</span></span><span :class="['text-sm font-semibold tnum', h.amt > 0 ? 'text-success' : '']">{{ money0(h.amt) }}</span></div><p v-if="!hist.length" class="px-4 py-8 text-center text-sm text-muted-foreground">Nothing yet.</p></div>
      <div v-else class="rounded-xl border bg-card p-4 text-sm"><div class="flex justify-between border-b pb-2.5"><span>{{ a.rec }}</span><span :class="['font-medium tnum', a.gap ? 'text-warning' : 'text-success']">{{ a.gap ? money0(a.gap) : 'matched' }}</span></div><p class="pt-2.5 text-xs text-muted-foreground">Each check compares what the books say with what you count or read off the statement.</p></div></div></div>
    <FooterBar><Btn full @click="S.sheet = 'recon'">Check this account</Btn></FooterBar>
    <Sheet :open="S.sheet === 'recon'" title="Check this account" :sub="'The books say ' + money(a.bal)" @close="S.sheet = null"><div class="px-4 pb-4"><p class="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">What is really there</p><label class="mt-1.5 flex h-12 items-center gap-2 rounded-md border-2 border-primary px-3"><span class="text-sm text-muted-foreground">TZS</span><input v-model.number="counted" type="text" inputmode="numeric" pattern="[0-9]*" aria-label="Counted" class="min-w-0 flex-1 bg-transparent text-right text-xl font-semibold tnum outline-none"></label>
      <p :class="['mt-3 rounded-md px-3 py-2 text-sm', counted === a.bal ? 'bg-success/10 text-success' : 'bg-warning/10 text-warning']">{{ counted === a.bal ? 'It matches.' : 'A gap of ' + money0(counted - a.bal) + '. Amina approves it.' }}</p></div><template #footer><Btn full @click="rec">Record the check</Btn></template></Sheet></div>` };
